// ================= Numbers Doctor v2 - shared library =================
// This exact text is embedded in the n8n Code node and in the three agent tools.
//
// DATA ADAPTER CONTRACT: loadData(caseId) must return three arrays:
//   source:     { order_id, date, region, currency, amount_local, amount_usd }   (system of record)
//   dashboard:  { order_id, date, region, amount_usd }                           (what the dashboard / BI export shows)
//   refreshLog: { date, region, status }                                         (load-job log)
// Default adapter = built-in sample data with seeded faults. Any BI tool that can export CSV
// (Power BI, Tableau, SAC, Excel) can feed the same three shapes.

const REGIONS = ['North', 'South', 'East', 'West'];
const CCY = { North: 'USD', South: 'INR', East: 'EUR', West: 'USD' };
const FX = { USD: 1, EUR: 1.08, INR: 0.012 };
const DAYS = Array.from({ length: 10 }, (_, i) => '2026-11-' + String(i + 1).padStart(2, '0'));
const r2 = x => Math.round(x * 100) / 100;
const sumUsd = rows => r2(rows.reduce((t, r) => t + r.amount_usd, 0));

// Seeded faults. Case 0 is a clean control. The agent never sees this table.
const CASES = {
  0: [],
  1: [{ type: 'partial_load', region: 'South', dates: ['2026-11-10'], logged: true }],
  2: [{ type: 'duplicate_load', region: 'East', dates: ['2026-11-05'] }],
  3: [{ type: 'currency_not_converted', region: 'East', dates: ['2026-11-07', '2026-11-08'] }],
  4: [{ type: 'partial_load', region: 'South', dates: ['2026-11-10'], logged: true },
      { type: 'duplicate_load', region: 'East', dates: ['2026-11-05'] }],
  5: [{ type: 'partial_load', region: 'West', dates: ['2026-11-03'], logged: false }],
  6: [{ type: 'currency_not_converted', region: 'South', dates: ['2026-11-09'] }],
  7: [{ type: 'partial_load', region: 'North', dates: ['2026-11-10'], logged: true },
      { type: 'currency_not_converted', region: 'South', dates: ['2026-11-04'] }],
  8: [{ type: 'duplicate_load', region: 'East', dates: ['2026-11-02'] },
      { type: 'duplicate_load', region: 'West', dates: ['2026-11-06'] }],
  9: [{ type: 'partial_load', region: 'North', dates: ['2026-11-08'], logged: true },
      { type: 'duplicate_load', region: 'East', dates: ['2026-11-05'] },
      { type: 'currency_not_converted', region: 'South', dates: ['2026-11-10'] }],
  10: [{ type: 'missing_single', region: 'West', dates: ['2026-11-09'], index: 1 }]
};

function loadData(caseId) {
  const source = [];
  let n = 1;
  REGIONS.forEach((region, r) => DAYS.forEach((date, di) => {
    for (let k = 0; k < 3; k++) {
      let local = 1000 + ((n * 37 + r * 101 + di * 13) % 900);
      if (CCY[region] === 'INR') local *= 80;
      source.push({ order_id: 'ORD-' + String(n).padStart(4, '0'), date, region, currency: CCY[region], amount_local: local, amount_usd: r2(local * FX[CCY[region]]) });
      n++;
    }
  }));
  const refreshLog = [];
  REGIONS.forEach(region => DAYS.forEach(date => refreshLog.push({ date, region, status: 'SUCCESS' })));
  let dashboard = source.map(s => ({ order_id: s.order_id, date: s.date, region: s.region, amount_usd: s.amount_usd }));
  const localById = {};
  source.forEach(s => { localById[s.order_id] = s.amount_local; });
  (CASES[caseId] || []).forEach(f => {
    const match = row => row.region === f.region && f.dates.includes(row.date);
    if (f.type === 'partial_load') {
      dashboard = dashboard.filter(row => !match(row));
      if (f.logged) refreshLog.forEach(l => { if (l.region === f.region && f.dates.includes(l.date)) l.status = 'FAILED'; });
    } else if (f.type === 'missing_single') {
      const victim = source.filter(match)[f.index || 0].order_id;
      dashboard = dashboard.filter(row => row.order_id !== victim);
    } else if (f.type === 'duplicate_load') {
      dashboard = dashboard.flatMap(row => match(row) ? [row, { ...row }] : [row]);
    } else if (f.type === 'currency_not_converted') {
      dashboard = dashboard.map(row => match(row) ? { ...row, amount_usd: localById[row.order_id] } : row);
    }
  });
  return { source, dashboard, refreshLog };
}

function parseQuery(query) {
  const parts = String(query).split('|').map(s => s.trim());
  return { caseId: Number(parts[0]), arg: parts[1] || '' };
}

// ---- Tool 1: drill-down by dimension (region, or date within a region) ----
function tool_drill_down(query) {
  const { caseId, arg } = parseQuery(query);
  const { source, dashboard } = loadData(caseId);
  const bits = (arg || 'region').split(':');
  const dim = bits[0];
  const val = bits[1] || '';
  if (dim !== 'region' && dim !== 'date') return JSON.stringify({ error: 'Input must be "<case>|region", "<case>|date" or "<case>|date:<Region>"' });
  let s = source, d = dashboard;
  if (dim === 'date' && val) { s = s.filter(r => r.region === val); d = d.filter(r => r.region === val); }
  const keys = [...new Set(s.map(r => r[dim]).concat(d.map(r => r[dim])))].sort();
  const rows = keys.map(k => {
    const sv = sumUsd(s.filter(r => r[dim] === k));
    const dv = sumUsd(d.filter(r => r[dim] === k));
    const o = {}; o[dim] = k; o.source_usd = sv; o.dashboard_usd = dv; o.gap_usd = r2(dv - sv);
    return o;
  }).filter(x => Math.abs(x.gap_usd) > 0.005).sort((a, b) => Math.abs(b.gap_usd) - Math.abs(a.gap_usd));
  const where = (dim === 'date' && val) ? " WHERE region = '" + val + "'" : '';
  return JSON.stringify({
    check: 'drill_down', dimension: dim, filter: (dim === 'date' && val) ? 'region=' + val : null,
    sql: 'SELECT COALESCE(s.k, d.k) AS ' + dim + ', s.v AS source_usd, d.v AS dashboard_usd, d.v - s.v AS gap_usd FROM (SELECT ' + dim + ' AS k, SUM(amount_usd) AS v FROM source_orders' + where + ' GROUP BY 1) s FULL JOIN (SELECT ' + dim + ' AS k, SUM(amount_usd) AS v FROM dashboard_export' + where + ' GROUP BY 1) d ON s.k = d.k WHERE d.v IS DISTINCT FROM s.v;',
    groups_checked: keys.length,
    groups_with_gap: rows,
    note: rows.length ? 'Only groups with a gap are listed.' : 'No gap in any group for this dimension.'
  });
}

// ---- Tool 2: refresh-log check ----
function tool_refresh_log(query) {
  const { caseId, arg } = parseQuery(query);
  const { refreshLog } = loadData(caseId);
  const scoped = arg && arg.toLowerCase() !== 'all';
  const rows = scoped ? refreshLog.filter(l => l.region === arg) : refreshLog;
  const bad = rows.filter(l => l.status !== 'SUCCESS');
  return JSON.stringify({
    check: 'refresh_log', scope: scoped ? arg : 'all',
    sql: "SELECT region, date, status FROM refresh_log WHERE status <> 'SUCCESS'" + (scoped ? " AND region = '" + arg + "'" : '') + ';',
    entries_checked: rows.length,
    failed_or_partial: bad,
    note: bad.length ? 'These load jobs did not finish with SUCCESS.' : 'Every load job reports SUCCESS. A SUCCESS status does not prove every row was loaded.'
  });
}

// ---- Tool 3: duplicate / missing / value-mismatch record check ----
function tool_record_integrity(query) {
  const { caseId } = parseQuery(query);
  const { source, dashboard } = loadData(caseId);
  const count = {}, firstDash = {};
  dashboard.forEach(d => { count[d.order_id] = (count[d.order_id] || 0) + 1; if (!firstDash[d.order_id]) firstDash[d.order_id] = d; });
  const byKey = rows => {
    const g = {};
    rows.forEach(r => { const k = r.region + '|' + r.date; (g[k] = g[k] || []).push(r); });
    return Object.keys(g).sort().map(k => ({ region: g[k][0].region, date: g[k][0].date, rows: g[k] }));
  };
  const ids = rows => rows.slice(0, 10).map(r => r.order_id);

  const missing = source.filter(s => !count[s.order_id]);
  const duplicated = source.filter(s => count[s.order_id] > 1);
  const mismatched = source.filter(s => count[s.order_id] && Math.abs(firstDash[s.order_id].amount_usd - s.amount_usd) > 0.01);

  return JSON.stringify({
    check: 'record_integrity',
    sql: {
      missing: 'SELECT s.* FROM source_orders s LEFT JOIN dashboard_export d USING (order_id) WHERE d.order_id IS NULL;',
      duplicates: 'SELECT order_id, COUNT(*) FROM dashboard_export GROUP BY 1 HAVING COUNT(*) > 1;',
      value_mismatch: 'SELECT s.order_id, s.amount_usd AS source_usd, d.amount_usd AS dashboard_usd, s.amount_local FROM source_orders s JOIN dashboard_export d USING (order_id) WHERE ABS(s.amount_usd - d.amount_usd) > 0.01;'
    },
    source_rows: source.length, dashboard_rows: dashboard.length,
    missing_rows: byKey(missing).map(g => ({ region: g.region, date: g.date, count: g.rows.length, order_ids: ids(g.rows), total_usd: sumUsd(g.rows) })),
    duplicate_rows: byKey(duplicated).map(g => ({ region: g.region, date: g.date, orders_duplicated: g.rows.length, order_ids: ids(g.rows), extra_usd: r2(g.rows.reduce((t, r) => t + r.amount_usd * (count[r.order_id] - 1), 0)) })),
    value_mismatches: byKey(mismatched).map(g => ({
      region: g.region, date: g.date, count: g.rows.length, currency: g.rows[0].currency, order_ids: ids(g.rows),
      source_usd: sumUsd(g.rows),
      dashboard_usd: r2(g.rows.reduce((t, r) => t + firstDash[r.order_id].amount_usd, 0)),
      dashboard_equals_local_amount: g.rows.every(r => Math.abs(firstDash[r.order_id].amount_usd - r.amount_local) < 0.01)
    }))
  });
}

// ---- Quick check: headline numbers only. The agent does the investigation. ----
const caseId = Number($input.first().json.case_id);
const { source, dashboard, refreshLog } = loadData(caseId);
const sourceTotal = sumUsd(source);
const dashboardTotal = sumUsd(dashboard);
const gap = r2(dashboardTotal - sourceTotal);
const failedJobs = refreshLog.filter(l => l.status !== 'SUCCESS').length;
const mismatch = Math.abs(gap) > 0.005 || dashboard.length !== source.length || failedJobs > 0;
return [{ json: {
  case_id: caseId, mismatch, sourceTotal, dashboardTotal, gap,
  gapPct: sourceTotal ? r2((gap / sourceTotal) * 100) : 0,
  sourceRows: source.length, dashboardRows: dashboard.length,
  startedAt: new Date().toISOString()
} }];

