// ---- Tool 1: drill-down by dimension (region, or date within a region) ----
function tool_drill_down(query) {
  const { caseId, arg } = parseQuery(query);
  const { source, dashboard } = loadData(caseId);
  const bits = (arg || 'region').split(':');
  const dim = bits[0];
  const val = bits[1] || '';
  if (dim !== 'region' && dim !== 'date') return JSON.stringify({ error: 'Input must be "<case>|region", "<case>|date" or "<case>|date:<Region>"' });
  let s = source, d = dashboard;
  if (dim === 'date' && val) { s = s.filter(r => r.region === val); d = d.filter(r => r.region === val); }
  const keys = [...new Set(s.map(r => r[dim]).concat(d.map(r => r[dim])))].sort();
  const rows = keys.map(k => {
    const sv = sumUsd(s.filter(r => r[dim] === k));
    const dv = sumUsd(d.filter(r => r[dim] === k));
    const o = {}; o[dim] = k; o.source_usd = sv; o.dashboard_usd = dv; o.gap_usd = r2(dv - sv);
    return o;
  }).filter(x => Math.abs(x.gap_usd) > 0.005).sort((a, b) => Math.abs(b.gap_usd) - Math.abs(a.gap_usd));
