// ---- Tool 3: duplicate / missing / value-mismatch record check ----
function tool_record_integrity(query) {
  const { caseId } = parseQuery(query);
  const { source, dashboard } = loadData(caseId);
  const count = {}, firstDash = {};
  dashboard.forEach(d => { count[d.order_id] = (count[d.order_id] || 0) + 1; if (!firstDash[d.order_id]) firstDash[d.order_id] = d; });
  const byKey = rows => {
    const g = {};
    rows.forEach(r => { const k = r.region + '|' + r.date; (g[k] = g[k] || []).push(r); });
    return Object.keys(g).sort().map(k => ({ region: g[k][0].region, date: g[k][0].date, rows: g[k] }));
  };
  const ids = rows => rows.slice(0, 10).map(r => r.order_id);

  const missing = source.filter(s => !count[s.order_id]);
  const duplicated = source.filter(s => count[s.order_id] > 1);
  const mismatched = source.filter(s => count[s.order_id] && Math.abs(firstDash[s.order_id].amount_usd - s.amount_usd) > 0.01);

  return JSON.stringify({
    check: 'record_integrity',
    sql: {
      missing: 'SELECT s.* FROM source_orders s LEFT JOIN dashboard_export d USING (order_id) WHERE d.order_id IS NULL;',
      duplicates: 'SELECT order_id, COUNT(*) FROM dashboard_export GROUP BY 1 HAVING COUNT(*) > 1;',
      value_mismatch: 'SELECT s.order_id, s.amount_usd AS source_usd, d.amount_usd AS dashboard_usd, s.amount_local FROM source_orders s JOIN dashboard_export d USING (order_id) WHERE ABS(s.amount_usd - d.amount_usd) > 0.01;'
    },
    source_rows: source.length, dashboard_rows: dashboard.length,
    missing_rows: byKey(missing).map(g => ({ region: g.region, date: g.date, count: g.rows.length, order_ids: ids(g.rows), total_usd: sumUsd(g.rows) })),
    duplicate_rows: byKey(duplicated).map(g => ({ region: g.region, date: g.date, orders_duplicated: g.rows.length, order_ids: ids(g.rows), extra_usd: r2(g.rows.reduce((t, r) => t + r.amount_usd * (count[r.order_id] - 1), 0)) })),
    value_mismatches: byKey(mismatched).map(g => ({
      region: g.region, date: g.date, count: g.rows.length, currency: g.rows[0].currency, order_ids: ids(g.rows),
      source_usd: sumUsd(g.rows),
      dashboard_usd: r2(g.rows.reduce((t, r) => t + firstDash[r.order_id].amount_usd, 0)),
      dashboard_equals_local_amount: g.rows.every(r => Math.abs(firstDash[r.order_id].amount_usd - r.amount_local) < 0.01)
    }))
  });
}

return tool_refresh_log(query);

